events.load:
sendme
sys0=0 // used by the spinner to check cnt for duration, see tmSpinner
if(tMsg2.txt=="")
{
  tMsg2.txt="HAUI TFT-Version: "+system.tftVersion.txt
}
if(system.firstRun.txt!="1")
{
  vis tMsg1,0
  vis tMsg2,0
  vis qrUrl,0
  tmSpinner.en=1
}else
{
  vis hSpinner,0
}

events.timer:
// update positions (max 30 frames)
vPosX.val=vFrame.val%30
vPosX.val%=10
vPosX.val*=140
vPosY.val=vFrame.val%30
vPosY.val/=10
vPosY.val*=140
// using multiple files for frames
if(vFrame.val<30)
{
  xpic hSpinner.x,hSpinner.y,140,140,vPosX.val,vPosY.val,11
}else
{
  xpic hSpinner.x,hSpinner.y,140,140,vPosX.val,vPosY.val,12
}
doevents
// update frame number
vFrame.val+=1
if(vFrame.val==60)
{
  vLoops.val+=1
}
vFrame.val%=60
// show message after some time (10 loops of the spinner)
if(vLoops.val==5)
{
  vis tMsg1,1
  vis tMsg2,1
}

